source("smoke_firm_dir/code/fxns/1_paths.R")
library(data.table)
input <- file.path(OUT_DIR,"static_pricing_subgame/observed_recovery_2026-10-27/fringe_market_recovery.csv")
out <- file.path(OUT_DIR,"dynamic_entry_exit/constant_market_size_2026-11-03")
dir.create(out,recursive=TRUE,showWarnings=FALSE)
hash <- tools::md5sum(input)
d <- fread(input);setorder(d,month)
stopifnot(nrow(d)==132L,!anyDuplicated(d$month),all(is.finite(d$M)),all(d$M>0))
last <- d[.N]
result <- data.table(benchmark_month=last$month,M_constant=last$M,definition="Selected demand market size: constant purchasing intensity times adult population",expectation="Latest observed M held fixed at all future horizons")
fwrite(result,file.path(out,"constant_market_size.csv"))
saveRDS(list(M_constant=last$M,benchmark_month=last$month,expectation="For a stationary solve at date t, M at all future dates equals latest observed M_t. Initial benchmark uses final sample month."),file.path(out,"constant_market_size_inputs.rds"))
stopifnot(identical(unname(hash),unname(tools::md5sum(input))))
fwrite(data.table(path=input,md5=unname(hash)),file.path(out,"input_hash.csv"))
writeLines(c("Retain the selected nested-logit definition and liquid-volume units; do not recalibrate shares or utilities.","Initial stationary benchmark uses December 2023 market size, held constant throughout the dynamic solve.","For historical-date exercises, each date may have a separate stationary solve holding its latest observed M fixed; this is not yet implemented.","This is a maintained expectation, not a claim about realized population. No population forecast or market-size transition is estimated.","Historical market sizes and pricing audits are unchanged. Checked 132 unique months, positive finite M, latest date selection and unchanged input hash."),file.path(out,"README.txt"))
print(result,digits=15)
